// Module 1: Transaction Pool
public class TransactionPool
{
    private readonly List<Transaction> _transactions = new List<Transaction>();
    private readonly Dictionary<string, List<TransactionOutput>> _unspentOutputs = new Dictionary<string, List<TransactionOutput>>();
    private readonly SHA256 _crypto = SHA256.Create();

    public void AddTransaction(Transaction transaction)
    {
        if (transaction == null)
            throw new ArgumentNullException(nameof(transaction));

        // Verify the transaction signature
        if (!VerifySignature(transaction))
        {
            throw new InvalidOperationException("Invalid transaction signature");
        }

        // Verify all inputs are valid (exist in unspent outputs)
        foreach (var input in transaction.Inputs)
        {
            if (!_unspentOutputs.TryGetValue(input.PreviousOutputId, out var outputs) ||
                outputs.Count == 0)
            {
                throw new InvalidOperationException($"Input {input.PreviousOutputId} not found in unspent outputs");
            }
        }

        // Create new outputs
        var newOutputs = new List<TransactionOutput>();
        foreach (var output in transaction.Outputs)
        {
            newOutputs.Add(output);
            _unspentOutputs[output.Id] = newOutputs;
        }

        // Remove used outputs
        foreach (var input in transaction.Inputs)
        {
            if (_unspentOutputs.TryGetValue(input.PreviousOutputId, out var outputs))
            {
                outputs.RemoveAll(o => o.Id == input.PreviousOutputId);
                if (outputs.Count == 0)
                {
                    _unspentOutputs.Remove(input.PreviousOutputId);
                }
            }
        }

        _transactions.Add(transaction);
    }

    public List<Transaction> GetPendingTransactions()
    {
        return _transactions.ToList();
    }

    public void ResetUnspentOutputs()
    {
        _unspentOutputs.Clear();
    }

    public void AddGenesisBlockOutputs(List<TransactionOutput> outputs)
    {
        foreach (var output in outputs)
        {
            _unspentOutputs[output.Id] = new List<TransactionOutput> { output };
        }
    }

    private bool VerifySignature(Transaction transaction)
    {
        if (transaction.Signature == null || transaction.PublicKey == null)
            return false;

        // Combine all inputs and outputs to create a message to sign
        var message = string.Join("|",
            transaction.Inputs.Select(i => $"{i.PreviousOutputId}:{i.Amount}"),
            transaction.Outputs.Select(o => $"{o.Id}:{o.Amount}:{o.Recipient}"));

